/* Exclusão atômica de medições e cobranças completas, com proteção das baixas. */
(function(root){'use strict';const D=root.Obras;let api,pending=false;
function target(state,kind,id){if(kind==='measurement'){let first=state.measurements.find(m=>m.id===id);if(!first)throw Error('Medição não encontrada.');let records=state.measurements.filter(m=>m.project===first.project&&m.number===first.number),receipts=state.receipts.filter(r=>!r.receivableId&&r.project===first.project&&r.number===first.number);return {kind,id,title:'medição '+first.number,records,receipts,project:first.project,number:first.number,amount:D.sum(records,m=>D.measurementValue(state,m))}}if(kind==='receivable'){let entry=(state.receivableEntries||[]).find(x=>x.id===id);if(!entry)throw Error('Conta a receber não encontrada.');return {kind,id,title:'conta a receber '+(entry.document||entry.description),records:[entry],receipts:state.receipts.filter(r=>r.receivableId===id),amount:entry.amount}}if(kind==='payable'){let group=root.EngefexPayables.groups(state).find(g=>g.id===id);if(!group)throw Error('Conta a pagar não encontrada.');let records=group.purchase?state.costs.filter(c=>c.purchase===group.purchase):group.records;return {kind,id,title:group.purchase?'conta da compra / nota e todas as suas parcelas':group.description,records,receipts:[],purchase:group.purchase,laborContract:records[0]?.laborContract,laborMeasurement:records[0]?.laborMeasurement,amount:D.sum(records,c=>c.amount)}}throw Error('Tipo de exclusão inválido.')}
function check(item){if(item.receipts.length)throw Error('Há recebimentos registrados nesta cobrança. Exclua ou corrija os recebimentos antes de excluir a medição ou a conta inteira.');if(item.kind==='payable'&&item.records.some(c=>['paid','incurred','paymentDiscount','paymentAddition'].some(k=>Number(c[k]||0)!==0)||c.paidDate))throw Error('Há pagamentos, descontos, acréscimos ou valores incorridos nesta conta. Corrija as baixas antes de excluir todas as parcelas.');}
function remove(state,kind,id){let item=target(state,kind,id);check(item);let next=D.clone(state),removed=item.records.map(record=>({kind:kind==='measurement'?'measurements':kind==='receivable'?'receivableEntries':'costs',record:D.clone(record)}));if(kind==='measurement')next.measurements=next.measurements.filter(m=>!item.records.some(r=>r.id===m.id));else if(kind==='receivable')next.receivableEntries=next.receivableEntries.filter(x=>x.id!==id);else if(item.purchase){next=root.EngefexPurchases.save(next,{...next.purchases.find(p=>p.id===item.purchase),status:'Cancelada'})}else if(item.laborContract){let contract=D.clone(next.laborContracts.find(c=>c.id===item.laborContract)),measurement=contract?.measurements.find(m=>m.id===item.laborMeasurement);if(!measurement)throw Error('Medição de mão de obra não encontrada.');measurement.status='Rascunho';next=root.EngefexLaborContracts.save(next,contract)}else next.costs=next.costs.filter(c=>!item.records.some(r=>r.id===c.id));D.validateMeasurementFinances(next);D.validateManualReceivables(next);D.validateReceivableInstallments(next);if(root.EngefexLaborContracts)root.EngefexLaborContracts.validateState(next);next.history.unshift({id:'FG-'+Date.now()+'-'+Math.random().toString(36).slice(2),time:new Date().toISOString(),kind:'financialGroupRemoval',record:id,action:kind==='measurement'?'Medição inteira excluída':kind==='receivable'?'Conta a receber e todas as parcelas excluídas':'Conta a pagar e todas as parcelas excluídas',before:{title:item.title,amount:item.amount},after:null,removed});return next}
async function execute(kind,id){if(pending)return;try{let snapshot=D.clone(api.getState()),item=target(snapshot,kind,id);check(item);let message=kind==='measurement'?'Excluir a '+item.title+' inteira, com todos os '+item.records.length+' itens e suas parcelas a receber?':kind==='receivable'?'Excluir a '+item.title+' inteira, incluindo a entrada e todas as parcelas?':item.purchase?'Excluir todas as '+new Set(item.records.map(c=>c.purchaseInstallment||c.id)).size+' parcelas desta conta, incluindo os rateios de todas as obras? A compra / nota ficará cancelada em Compras e notas.':item.laborContract?'Excluir esta conta a pagar? A medição correspondente voltará a Rascunho no contrato de mão de obra.':'Excluir esta conta a pagar?';if(!confirm(message+'\nOs registros removidos permanecerão no histórico.'))return;if(JSON.stringify(api.getState())!==JSON.stringify(snapshot))throw Error('Os dados mudaram. Atualize a lista antes de excluir.');let next=remove(snapshot,kind,id);pending=true;if(await api.save(next)===false)throw Error('O servidor não confirmou a exclusão. Atualize os dados antes de tentar novamente.');api.render();api.toast('Exclusão concluída.')}catch(e){api.toast(e.message)}finally{pending=false}}
root.EngefexFinancialRemoval={target,remove,busy:()=>pending,init:bridge=>api=bridge,handle(action){for(let [prefix,kind]of [['remove-measurement-group:','measurement'],['remove-payable-group:','payable'],['remove-receivable-group:','receivable']])if(action?.startsWith(prefix)){return execute(kind,action.slice(prefix.length)),true}return false}};
})(typeof window==='undefined'?globalThis:window);
